From d9c56f9b88305973bbb2a9b44d3dc4f264b7ac2f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:28:45 +0100
Subject: [PATCH] logout-greeter: offer to save the session from the logout
 screen

With "Restore manually saved session", the only ways to save were the
launcher menus and KRunner. The greeter now forwards a save request from
the logout screen, and ksmserver lets a running save finish first.

BUG: 46923
---
 ksmserver/logout.cpp           | 1 +
 logout-greeter/shutdowndlg.cpp | 7 +++++++
 logout-greeter/shutdowndlg.h   | 1 +
 3 files changed, 9 insertions(+)

diff --git a/ksmserver/logout.cpp b/ksmserver/logout.cpp
index c1daa435d7..956eec1557 100644
--- a/ksmserver/logout.cpp
+++ b/ksmserver/logout.cpp
@@ -90,6 +90,7 @@ void KSMServer::performLogout()
     }
     if (state != Idle) {
         QTimer::singleShot(1000, this, &KSMServer::performLogout);
+        return;
     }

     auto setStateReply = m_kwinInterface->setState(KWinSessionState::Saving);
diff --git a/logout-greeter/shutdowndlg.cpp b/logout-greeter/shutdowndlg.cpp
index ce552d3ca0..be05d5878c 100644
--- a/logout-greeter/shutdowndlg.cpp
+++ b/logout-greeter/shutdowndlg.cpp
@@ -103,6 +103,7 @@ KSMShutdownDlg::KSMShutdownDlg(QQmlEngine *engine, ShutdownType sdtype, bool win
     mapSpdMethods->insert(QStringLiteral("HibernateState"), m_session.canHibernate());
     context->setContextProperty(QStringLiteral("spdMethods"), mapSpdMethods);
     context->setContextProperty(QStringLiteral("canLogout"), m_session.canLogout());
+    context->setContextProperty(u"canSaveSession"_s, m_session.canSaveSession());

     // Trying to access a non-existent context property throws an error, always create the property and then update it later
     context->setContextProperty(u"rebootToFirmwareSetup"_s, false);
@@ -241,6 +242,7 @@ void KSMShutdownDlg::init(const KPackage::Package &package)
     connect(rootObject(), SIGNAL(cancelRequested()), SLOT(reject()));
     connect(rootObject(), SIGNAL(lockScreenRequested()), SLOT(slotLockScreen()));
     connect(rootObject(), SIGNAL(cancelSoftwareUpdateRequested()), SLOT(slotCancelSoftwareUpdate()));
+    connect(rootObject(), SIGNAL(saveSessionRequested()), SLOT(slotSaveSession()));

     KWindowEffects::enableBlurBehind(this, true);
     if (m_windowed) {
@@ -319,6 +321,11 @@ void KSMShutdownDlg::slotHaltUpdate()
 #endif
 }

+void KSMShutdownDlg::slotSaveSession()
+{
+    m_session.saveSession();
+}
+
 void KSMShutdownDlg::slotSuspend(int spdMethod)
 {
     m_bootOption.clear();
diff --git a/logout-greeter/shutdowndlg.h b/logout-greeter/shutdowndlg.h
index a20d43ddc8..9c460d8b14 100644
--- a/logout-greeter/shutdowndlg.h
+++ b/logout-greeter/shutdowndlg.h
@@ -60,6 +60,7 @@ public Q_SLOTS:
     void slotSuspend(int);
     void slotLockScreen();
     void slotCancelSoftwareUpdate();
+    void slotSaveSession();

 Q_SIGNALS:
     void accepted();
-- 
2.53.0
